#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    /**
     * 方法一：Kadane's Algorithm（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int maxSubArray(std::vector<int>& nums) {
        int currentSum = 0;
        int maxSum = INT_MIN;

        for (int num : nums) {
            // 決定是繼續累加還是重新開始
            currentSum = std::max(num, currentSum + num);
            // 更新最大值
            maxSum = std::max(maxSum, currentSum);
        }

        return maxSum;
    }

    /**
     * 方法二：動態規劃
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int maxSubArray_dp(std::vector<int>& nums) {
        int maxSum = nums[0];
        int prevSum = nums[0];

        for (int i = 1; i < nums.size(); i++) {
            prevSum = std::max(nums[i], prevSum + nums[i]);
            maxSum = std::max(maxSum, prevSum);
        }

        return maxSum;
    }
};

